import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.BX_mlWST.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"title":"Getting Started","prev":{"text":"Introduction","link":"/Main/beginners-guide/Getting-Started/introduction"},"next":{"text":"Harvesting","link":"/Main/beginners-guide/Early-Game/Harvesting"}},"headers":[],"relativePath":"Main/beginners-guide/Getting-Started/getting-started.md","filePath":"Main/beginners-guide/Getting-Started/getting-started.md"}'),n={name:"Main/beginners-guide/Getting-Started/getting-started.md"};function s(o,e,l,d,g,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>When you first join the game, you begin with a small farm and a set of starter equipment that allows you to start farming immediately. These tools are designed to help new players learn the basic farming mechanics before expanding into larger operations.</p><h2 id="starter-equipment" tabindex="-1">Starter Equipment <a class="header-anchor" href="#starter-equipment" aria-label="Permalink to &quot;Starter Equipment&quot;">​</a></h2><p>Every new player starts with the following <strong>level 1 equipment</strong>:</p><ul><li>level 1 Pickup</li><li>Level 1 Crop Trailer</li><li>Level 1 Harvester</li><li>Level 1 Plow</li><li>Level 1 Cultivator</li><li>Level 1 Seeder</li></ul><p>This equipment allows you to perform all the essential beginner farming tasks needed to begin producing your own crops.</p><h2 id="understanding-the-farming-process" tabindex="-1">Understanding the Farming Process <a class="header-anchor" href="#understanding-the-farming-process" aria-label="Permalink to &quot;Understanding the Farming Process&quot;">​</a></h2><p>The basic farming process follows a simple loop that you will repeat to progress throughout the early stages of the game:</p><ul><li>Plow the field to prepare the soil.</li><li>Cultivate the land to make it ready for planting.</li><li>Plant seeds using the seeder.</li><li>Wait for crops to grow</li><li>Harvest the crops using the harvester</li><li>Transport the crops using your pickup truck and trailer to sell them.</li></ul><h2 id="completing-tasks" tabindex="-1">Completing Tasks <a class="header-anchor" href="#completing-tasks" aria-label="Permalink to &quot;Completing Tasks&quot;">​</a></h2><p>The game includes a task system that provides players with objectives to complete. Tasks refresh every 2 hours and are split into three different sections, each containing four tasks.</p><p>Completing tasks is a good way to earn Xp towards unlocking something new. That could be a new factory, new equipment or even unlocking a whole new way of farming.</p><h2 id="building-your-early-income" tabindex="-1">Building Your Early Income <a class="header-anchor" href="#building-your-early-income" aria-label="Permalink to &quot;Building Your Early Income&quot;">​</a></h2><p>your first harvests will provide the money needed to exand your farm. As you continue farming, you can upgrade vehicles, purchase new equipment, and unlock addition systems such as animals and factries.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Now that you understand the starter equipment, farming process and the task system, the next section will guide through completing your first harvest and earning your first bit of money</p>',16)])])}const c=t(n,[["render",s]]);export{p as __pageData,c as default};
